command:
$ErrorActionPreference = 'Stop'
$repo = [Environment]::GetEnvironmentVariable('DCOIR_REPO_ROOT','Machine')
if ([string]::IsNullOrWhiteSpace($repo)) { throw 'DCOIR_REPO_ROOT is not configured' }
$branch = 'issue-484-lane-separation-scoring'
$expected = '9fb09e4ccd5f111ae59bc091007ddf4bba56a908'
$remoteLine = git -C $repo ls-remote origin ('refs/heads/' + $branch)
if ($LASTEXITCODE -ne 0 -or -not $remoteLine) { throw 'Unable to read PR branch head' }
$remote = ($remoteLine -split '\s+')[0]
if ($remote -ne $expected) { throw ('PR head drift: expected ' + $expected + ', got ' + $remote) }
git -C $repo fetch --no-tags origin $branch
if ($LASTEXITCODE -ne 0) { throw 'git fetch failed' }
$worktree = Join-Path $env:RUNNER_TEMP 'issue484-pr501-postcopilot-exact-head'
if (Test-Path -LiteralPath $worktree) { Remove-Item -LiteralPath $worktree -Recurse -Force }
try {
  git -C $repo worktree add --detach $worktree $expected
  if ($LASTEXITCODE -ne 0) { throw 'git worktree add failed' }
  Push-Location $worktree
  try {
    python -m py_compile project_sources/gemini/tools/lib/gemini_behavioral_replay_scoring.py project_sources/gemini/tools/validate_gemini_lane_separation_scoring.py
    if ($LASTEXITCODE -ne 0) { throw 'Python syntax validation failed' }
    python project_sources/gemini/tools/validate_gemini_lane_separation_scoring.py
    if ($LASTEXITCODE -ne 0) { throw 'Focused lane-separation regression validation failed' }
    $outDir = Join-Path $env:RUNNER_TEMP 'issue484-pr501-postcopilot-replay-out'
    if (Test-Path -LiteralPath $outDir) { Remove-Item -LiteralPath $outDir -Recurse -Force }
    python project_sources/gemini/tools/run_gemini_behavioral_replay_validation_suite.py --fixtures-root project_sources/gemini/fixtures/behavioral_replay --output-dir $outDir
    if ($LASTEXITCODE -ne 0) { throw 'Full deterministic Gemini behavioral replay validation failed' }
    $dirty = git status --porcelain
    if ($LASTEXITCODE -ne 0) { throw 'git status failed' }
    if ($dirty) { throw ('Validation dirtied worktree: ' + ($dirty -join '; ')) }
    Write-Host 'PR #501 post-Copilot exact-head validation passed.'
  } finally { Pop-Location }
} finally {
  git -C $repo worktree remove --force $worktree 2>$null
  git -C $repo worktree prune 2>$null
}
